arguments.command:
node -e '
const path = require("node:path");
const { lstat, realpath, mkdir, open, link, unlink } = require("node:fs/promises");
const { randomUUID } = require("node:crypto");

const candidateChunks = [];
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => candidateChunks.push(chunk));
process.stdin.on("end", async () => {
  const candidate = candidateChunks.join("");
  const lexicalRoot = path.resolve(process.cwd());
  const root = await realpath(lexicalRoot);
  const sourcePath = path.join(root, "bin/csl-agent-kit.js");
  const sourceStat = await lstat(sourcePath);
  if (sourceStat.isSymbolicLink() || !sourceStat.isFile()) throw new Error("Unsafe analysis target");
  const canonicalSource = await realpath(sourcePath);
  const sourceRelative = path.relative(root, canonicalSource);
  if (sourceRelative === ".." || sourceRelative.startsWith(`..${path.sep}`) || path.isAbsolute(sourceRelative)) {
    throw new Error("Analysis target escapes Git root");
  }

  const namespace = path.join(root, "docs/analysis/components/file");
  const target = path.join(namespace, "bin/csl-agent-kit.js.md");
  const namespaceRelative = path.relative(namespace, target);
  if (namespaceRelative === ".." || namespaceRelative.startsWith(`..${path.sep}`) || path.isAbsolute(namespaceRelative)) {
    throw new Error("Active report escapes output namespace");
  }

  const parent = path.dirname(target);
  const identities = new Map();
  const rememberDirectory = async (directory, allowCreate) => {
    let stat;
    try {
      stat = await lstat(directory);
    } catch (error) {
      if (error.code !== "ENOENT" || !allowCreate) throw error;
      try {
        await mkdir(directory);
      } catch (mkdirError) {
        if (mkdirError.code !== "EEXIST") throw mkdirError;
      }
      stat = await lstat(directory);
